<script setup lang="ts">
import {computed} from 'vue'
import {useAuth} from '../stores/auth'
import {useResource,formatDate} from '../composables/useData'
import PageHeader from '../components/PageHeader.vue'
import LoadState from '../components/LoadState.vue'
import Icon from '../components/Icon.vue'
const auth=useAuth(),units=useResource('units'),faqs=useResource('faqs',auth.has('faq.review')),gaps=useResource('gaps',auth.has('gaps.manage'))
const pending=computed(()=>faqs.items.value.filter(f=>f.status==='pending_review').length),unresolved=computed(()=>gaps.items.value.filter(g=>g.status==='unresolved').length),ungranted=computed(()=>units.items.value.filter(u=>!u.acl.length).length)
</script>
<template><PageHeader title="知识工作台" description="让已有知识持续可用，让未被回答的问题得到补充。"><RouterLink v-if="auth.has('knowledge.import')" to="/knowledge/import" class="btn primary"><Icon name="upload"/>导入文档</RouterLink></PageHeader><LoadState :loading="units.loading.value" :error="units.error.value||faqs.error.value||gaps.error.value" @retry="units.load();faqs.load();gaps.load()"><div class="work-queues"><RouterLink to="/knowledge/units" class="queue"><span>待配置数据授权</span><strong>{{ungranted}}</strong><p>默认不可访问，请确认授权范围 <Icon name="arrow" :size="16"/></p></RouterLink><RouterLink v-if="auth.has('faq.review')" to="/settlement/recommendations" class="queue"><span>待审核 FAQ</span><strong>{{pending}}</strong><p>核对答案后，沉淀为团队常用知识 <Icon name="arrow" :size="16"/></p></RouterLink><RouterLink v-if="auth.has('gaps.manage')" to="/settlement/gaps" class="queue"><span>待补充知识缺口</span><strong>{{unresolved}}</strong><p>从真实问题出发，补全知识 <Icon name="arrow" :size="16"/></p></RouterLink></div><section class="panel"><div class="panel-head"><h2>最近更新</h2><RouterLink to="/knowledge/units">查看全部 →</RouterLink></div><div v-for="unit in units.items.value.slice(0,6)" :key="unit.id" class="recent-unit"><Icon name="book"/><div><RouterLink v-if="!unit.restricted" :to="`/knowledge/units/${unit.id}`">{{unit.title}}</RouterLink><span v-else>{{unit.title}}</span><p>{{unit.code}} · {{formatDate(unit.updatedAt)}}</p></div><span class="status" :class="unit.status==='published'?'success':''">{{unit.status==='published'?'已发布':'草稿'}}</span></div><div v-if="!units.items.value.length" class="empty-inline">暂无知识，请先导入或新建。</div></section></LoadState></template>
<style scoped>.work-queues{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;margin-bottom:24px}.queue{padding:22px;background:var(--panel);border-radius:4px}.queue>span{font-size:12px;color:var(--muted)}.queue strong{display:block;font-size:32px;font-weight:500;margin:18px 0}.queue p{font-size:11px;color:var(--faint);line-height:1.8;display:flex;align-items:center;justify-content:space-between;gap:12px}.queue:hover{background:#202723}.recent-unit{display:flex;align-items:center;gap:14px;padding:18px 0;border-bottom:1px solid var(--line);font-size:13px}.recent-unit:last-child{border:0}.recent-unit>svg{color:var(--faint)}.recent-unit>div{flex:1;min-width:0}.recent-unit p{font-size:11px;color:var(--faint);margin-top:7px}@media(max-width:640px){.work-queues{grid-template-columns:1fr}.queue{padding:18px}.queue strong{margin:12px 0}.recent-unit{gap:10px;font-size:12px}}</style>
